BEGIN;































-- ---------------------------------------------------------
-- Sync Identity Sequences with Max Generated Primary Keys
-- ---------------------------------------------------------
SELECT setval(pg_get_serial_sequence('stores', 'id'), COALESCE((SELECT MAX(id) FROM stores), 1));
SELECT setval(pg_get_serial_sequence('routes', 'id'), COALESCE((SELECT MAX(id) FROM routes), 1));
SELECT setval(pg_get_serial_sequence('trucks', 'id'), COALESCE((SELECT MAX(id) FROM trucks), 1));
SELECT setval(pg_get_serial_sequence('employees', 'id'), COALESCE((SELECT MAX(id) FROM employees), 1));
SELECT setval(pg_get_serial_sequence('customers', 'id'), COALESCE((SELECT MAX(id) FROM customers), 1));
SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM products), 1));
SELECT setval(pg_get_serial_sequence('orders', 'id'), COALESCE((SELECT MAX(id) FROM orders), 1));
SELECT setval(pg_get_serial_sequence('order_items', 'id'), COALESCE((SELECT MAX(id) FROM order_items), 1));
SELECT setval(pg_get_serial_sequence('train_schedules', 'id'), COALESCE((SELECT MAX(id) FROM train_schedules), 1));
SELECT setval(pg_get_serial_sequence('train_allocations', 'id'), COALESCE((SELECT MAX(id) FROM train_allocations), 1));
SELECT setval(pg_get_serial_sequence('truck_schedules', 'id'), COALESCE((SELECT MAX(id) FROM truck_schedules), 1));
SELECT setval(pg_get_serial_sequence('truck_item_deliveries', 'id'), COALESCE((SELECT MAX(id) FROM truck_item_deliveries), 1));

COMMIT;
